"""Original obesity/metabolic chapter: assessment and safe therapy selection."""
from qbank_authoring import question,ref,finalize
OB=ref('Lancet Commission: Definition and Diagnostic Criteria of Clinical Obesity, 2025','https://pmc.ncbi.nlm.nih.gov/articles/PMC11870235/')
PH=ref('ADA: Pharmacologic Treatment of Obesity in Adults, 2026','https://doi.org/10.2337/doci25-0008')
SU=ref('ASMBS/IFSO: Indications for Metabolic and Bariatric Surgery, 2022','https://pmc.ncbi.nlm.nih.gov/articles/PMC9834364/')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('Why should BMI not be the sole assessment of obesity-related health impairment?', 'It does not directly measure fat distribution, body composition or adiposity-related organ dysfunction',[
 ('BMI has no useful population or screening role','It remains useful but is incomplete for individual diagnosis.'),('Every elevated BMI proves identical metabolic risk','Risk differs with adiposity, distribution, ancestry and clinical consequences.'),('A normal BMI excludes excess visceral fat in every person','Some people have adverse adiposity despite a lower BMI.')],
 'Use anthropometry and clinical function together', '**Waist measures or direct body-composition assessment can complement BMI.**',['The 2025 Commission distinguishes excess adiposity from established dysfunction due to adiposity.','The framework is a consensus approach and implementation varies.'], '**Evaluate the person’s actual disease burden.**',['Assess metabolic, mechanical and functional consequences.','Avoid reducing eligibility or care to a single uncontextualized number.'],[['BMI','Useful indirect measure'],['Waist/body composition','Distribution and adiposity'],['Clinical assessment','Organ and functional effects']],[OB])
q('In the 2025 Commission framework, what distinguishes clinical from preclinical obesity?', 'Current organ or functional impairment attributable to excess adiposity',[
 ('A universal BMI difference of exactly five units','The distinction is based on health impairment, not one fixed BMI separation.'),('Any future statistical risk alone equals established organ dysfunction','Risk and present disease are distinguished.'),('Preclinical obesity implies no future risk or need for care','Risk reduction and monitoring remain relevant.')],
 'The framework separates present illness from future vulnerability', '**Clinical obesity includes adiposity-related dysfunction of organs, tissues or daily activities.**',['Preclinical obesity has excess adiposity with preserved function.','Comorbid disease still needs appropriate causal assessment.'], '**Match treatment intensity to clinical needs and risk.**',['Do not use the category as a reason to withhold preventive care.','Discuss the framework without presenting it as a universally adopted legal definition.'],[['Clinical','Present attributable impairment'],['Preclinical','Preserved function with future risk'],['Care','Risk and needs based']],[OB])
q('An adult seeks obesity treatment. What is the most useful initial assessment principle?', 'Review complications, medications, eating and activity patterns, sleep, mental health and selected secondary causes',[
 ('Order a cortisol panel for every patient regardless of phenotype','Endocrine testing should be guided by clinical suspicion.'),('Assume weight reflects a single voluntary behavior','Obesity has biological, environmental and treatment-related contributors.'),('Ignore medicines that promote weight gain','Medication review can reveal modifiable contributors.')],
 'Assessment should identify treatable drivers and consequences', '**Some psychiatric, diabetes and anti-inflammatory drugs can promote weight gain.**',['Sleep apnea, mobility problems and food access affect treatment feasibility.','Cushing-specific signs or other clues justify targeted endocrine testing.'], '**Use respectful shared goals.**',['Health, function and quality of life matter alongside weight.','Choose interventions that fit the person’s resources and preferences.'],[['Drivers','Biology, environment and medicines'],['Consequences','Metabolic/mechanical/function'],['Testing','Clinical suspicion directed']],[OB,PH],'clinical_scenario')
q('What best characterizes effective nutritional treatment for obesity?', 'A sustainable energy deficit using an eating pattern matched to preferences, health needs and practical circumstances',[
 ('One named diet is mandatory and superior for every person','Adherence and suitability vary.'),('Lifestyle treatment should stop once medication begins','Nutrition and activity remain complementary.'),('Only the scale matters and nutritional adequacy is irrelevant','Protein, micronutrients and function remain important.')],
 'The practical plan matters more than a diet label', '**Different patterns can work when they create a sustainable deficit.**',['Diet quality and adequate protein help preserve health during loss.','Behavioral support improves implementation.'], '**Use follow-up to adjust barriers.**',['Avoid stigmatizing failure language.','Assess lean mass, symptoms and disordered eating when relevant.'],[['Mechanism','Sustainable energy deficit'],['Selection','Preference and medical context'],['Support','Ongoing behavioral and nutritional care']],[PH,OB])
q('Why can weight regain occur after substantial intentional weight loss despite continued effort?', 'Compensatory appetite and energy-expenditure changes oppose maintenance',[
 ('Regain proves all previous effort was fabricated','Biological adaptation is real.'),('Obesity is invariably cured after a brief loss','Relapse risk can persist.'),('Medication or surgery guarantees no future regain','Long-term follow-up remains necessary.')],
 'Maintenance is an active phase of chronic care', '**Weight loss can increase hunger and reduce energy expenditure relative to prior expectations.**',['Environment and treatment access also influence regain.','The magnitude varies between individuals.'], '**Plan maintenance from the start.**',['Continue effective supportive therapy when appropriate.','Reassess rather than blame when weight returns.'],[['Adaptation','Higher appetite/lower expenditure'],['Course','Chronic relapse risk'],['Response','Maintenance support and treatment review']],[PH,OB])
q('A patient loses substantial weight on effective obesity medication and asks to stop immediately. What counseling is appropriate?', 'Explain that treatment is often long term and stopping can lead to regain; make an individualized maintenance plan',[
 ('All medicines must stop as soon as a short-term target is reached','This can remove the support maintaining the response.'),('Continuing treatment is always mandatory regardless of harms or preference','Benefit-risk and the person’s choices still matter.'),('Weight regain after withdrawal means the drug never worked','Withdrawal can reveal persistent biology.')],
 'An achieved result may depend on continuing therapy', '**Obesity pharmacotherapy is generally used as chronic treatment when effective and tolerated.**',['Adverse effects, pregnancy plans, cost and preference can require change.','Long-term outcome evidence differs by agent.'], '**Plan a safe transition rather than an abrupt unsupported gap.**',['Maintain nutrition and activity support.','Review weight, metabolic and functional outcomes after changes.'],[['Effective therapy','Often continued'],['Stopping','Regain risk'],['Decision','Individual benefit, harm and feasibility']],[PH],'clinical_scenario')
q('A woman using an oral contraceptive starts tirzepatide for obesity. What specific counseling is appropriate?', 'Use a nonoral method or add a barrier method for four weeks after initiation and after each dose escalation',[
 ('No interaction is possible because contraception is unrelated to gastric emptying','Tirzepatide can affect oral contraceptive exposure.'),('The advice applies only after a pregnancy occurs','Prevention advice is needed before exposure.'),('Every GLP-1-based product has identical oral-contraceptive interaction data','The specific medicine and label matter.')],
 'Delayed gastric emptying can affect another oral medicine', '**Current guidance highlights this clinically relevant tirzepatide interaction.**',['The four-week precaution repeats after dose escalation.','Vomiting and diarrhea can create additional contraceptive issues.'], '**Discuss pregnancy intention and a reliable plan.**',['Use local product guidance.','Do not infer contraceptive reliability from weight or prior infertility.'],[['Exposure','Tirzepatide initiation/escalation'],['Precaution','Nonoral or additional barrier'],['Duration','Four weeks after each relevant change']],[PH],'clinical_scenario')
q('A patient receiving semaglutide for weight reduction plans pregnancy. What is the appropriate principle?', 'Stop in advance according to the product’s washout guidance and create a preconception weight and glucose plan',[
 ('Continue all weight-loss medicines throughout pregnancy by default','Intentional pharmacological weight loss is not routine pregnancy care.'),('Stop all diabetes therapy without replacement if diabetes coexists','Safe glycemic management remains essential.'),('A weight target removes the need for reproductive counseling','Drug exposure and nutrition still matter.')],
 'Weight treatment and pregnancy have different goals', '**Semaglutide weight-management labeling advises stopping at least two months before planned pregnancy.**',['Other medicines have their own guidance.','Nutrition and diabetes treatment need coordinated review.'], '**Avoid an unplanned care gap.**',['Review contraception while the drug remains active.','Plan follow-up for appetite, weight and glycemia after withdrawal.'],[['Before conception','Product-specific washout'],['Semaglutide weight indication','At least two months'],['Care','Nutrition and glycemic transition']],[PH],'clinical_scenario')
q('Which history is especially important before prescribing naltrexone-bupropion for obesity?', 'Current opioid use, seizure risk and uncontrolled hypertension',[
 ('Only a history of mild seasonal rhinitis','This does not capture the major contraindications.'),('A normal A1C excludes all relevant risks','The contraindications are not determined by glycemia.'),('Naltrexone has no interaction with opioid analgesia','It antagonizes opioid receptors and can precipitate withdrawal.')],
 'A combination medicine inherits the risks of both components', '**Naltrexone blocks opioid action and bupropion can lower seizure threshold.**',['Blood pressure and psychiatric context matter.','Other bupropion-containing products must be reconciled.'], '**Choose an alternative when contraindications apply.**',['Ask about prescribed and nonprescribed opioids.','Plan pain-management needs before treatment.'],[['Naltrexone','Opioid antagonism'],['Bupropion','Seizure and blood-pressure concerns'],['Selection','Full medication and risk review']],[PH])
q('Which safety issue is central to phentermine-topiramate use in a person who could become pregnant?', 'Teratogenic risk requiring reliable pregnancy prevention and testing according to the product program',[
 ('The medicine improves fetal neural development and needs no precautions','Topiramate exposure carries fetal risk.'),('Infertility associated with obesity guarantees no pregnancy','Fertility can improve with weight change.'),('A negative test at first prescription eliminates all later risk','Ongoing precautions are needed.')],
 'Treatment can change fertility while a drug remains unsuitable for pregnancy', '**Topiramate-related oral-cleft risk is an important warning.**',['Cardiovascular, psychiatric and cognitive effects also affect selection.','Dose changes and stopping require product-specific guidance.'], '**Use a clear reproductive safety plan.**',['Do not assume oral contraceptive advice is identical for every obesity medicine.','Discuss alternatives when reliable prevention is not feasible.'],[['Major concern','Fetal harm'],['Prevention','Reliable contraception/testing'],['Other issues','Cardiac, mood and cognitive context']],[PH])
q('What is the principal mechanism of orlistat?', 'Inhibition of gastrointestinal lipases, reducing dietary fat absorption',[
 ('Direct GLP-1 receptor agonism','That is a different drug class.'),('Central opioid receptor antagonism','That is naltrexone’s relevant mechanism.'),('Stimulation of thyroid hormone synthesis','That is not its action.')],
 'The intestinal mechanism predicts adverse effects', '**Unabsorbed fat can cause oily stools, urgency and gastrointestinal symptoms.**',['Fat-soluble vitamin status and medication interactions need consideration.','Meal composition affects tolerability.'], '**Use appropriate supplementation and interaction guidance.**',['Separate relevant products according to instructions.','Assess persistent GI problems rather than assuming every symptom is expected.'],[['Action','Lipase inhibition'],['Effect','Less fat absorption'],['Monitoring','GI tolerance, vitamins and interactions']],[PH])
q('A suitable adult has BMI 37 kg/m² without a major diagnosed metabolic complication. What do ASMBS/IFSO 2022 recommendations state?', 'Metabolic/bariatric surgery is recommended for suitable individuals with BMI at least 35 regardless of comorbidity severity',[
 ('Surgery requires BMI at least 40 in every modern guideline','The 2022 recommendations broadened eligibility.'),('Every eligible person must undergo surgery regardless of preference','Eligibility supports informed discussion, not compulsion.'),('No nutritional or psychosocial assessment is needed if BMI qualifies','Comprehensive evaluation remains essential.')],
 'Eligibility and individual suitability are separate questions', '**The guideline also considers surgery at BMI 30–34.9 with metabolic disease or inadequate durable nonsurgical response.**',['Asian-population thresholds are lower.','Local access and authorization can differ.'], '**Use multidisciplinary informed selection.**',['Discuss expected benefit, operative risk and lifelong follow-up.','Do not present a BMI threshold as the whole decision.'],[['BMI at least 35','Guideline recommendation if suitable'],['Lower BMI','Selected metabolic context'],['Process','Multidisciplinary shared decision']],[SU],'clinical_scenario')
